 public sealed class Voice:KokoroEngine {public static string FailText="";public static Dictionary<string,double> Durations=new Dictionary<string,double>();public static Dictionary<string,int> Calls=new Dictionary<string,int>();public override void CheckFiles(){}public override Wave Generate(string text,double speed,string path){if(!Calls.ContainsKey(text))Calls[text]=0;Calls[text]++;if(text==FailText)throw new IOException("fixture candidate TTS failed");return Tone((Durations.ContainsKey(text)?Durations[text]:new Cue{Text=text}.Words*.3)/speed);}}
